    [76] = {
      beijing = 3200,
      dialog = 3,
      music = "1012_2023Halloween",
      renwu = "npc",
      sentence = "Unfortunately, I didn't even make it to the end of the red carpet when my strength gave out. And so, amidst a sea of gasps, Lucien carried me onto the throne.",
