    },
    [81] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "The poison's assault upon my body left me powerless, and meanwhile, he was a brilliant and wise King. The kingdom prospered in his hands, and everything ran like clockwork.",
      next = {82}
    },
    [82] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "But he still insisted on seeking my opinion on every decree, whether I was unconscious or awake.",
      next = {83}
    },
    [83] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "And when he made a formal proclamation, he would always add the phrase \"by the will of the King and the Queen\".",
      next = {84}
    },
    [84] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "I had gone from an accursed, pitiful woman to a sharp and resourceful monarch, steeled by the hardships she had endured, and who overthrew the tyrannical rule of the previous Duke along with her husband, who himself had feigned death to do it.",
      next = {85}
    },
    [85] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "It was clear that no one had ever seen me, and yet they all sang my praises.",
