      roleanim = 1.1,
      sentence = "A physician from the Far East has arrived in the capital. This is a concoction he and I worked up together. Try a bit, will you?",
      voice = 2,
      next = {101}
    },
    [101] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201201,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "This tone reminded me of \"Simon\". I pressed the tip of my tongue against my teeth before mustering a response of \"fine\".",
      next = {102}
    },
    [102] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201105,
      role3 = 201202,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "A glow of delighted surprise lit up his eyes. He carefully held the medicine to my lips and awaited my reaction.",
      next = {103}
    },
    [103] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201105,
      role3 = 201202,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "Does your head still hurt?",
      voice = 2,
      next = {104}
    },
    [104] = {
      beijing = 3181,
      dhead = 106,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201205,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "Still.",
      next = {105}
    },
    [105] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201205,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "Is it any easier to breathe?",
      voice = 2,
      next = {106}
    },
    [106] = {
      beijing = 3181,
      dhead = 106,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201205,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "No.",
      next = {107}
    },
    [107] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201205,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "...",
      next = {108}
    },
    [108] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201104,
      role3 = 201206,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      sentence = "Then... your heart?",
      voice = 2,
      next = {109}
    },
    [109] = {
      beijing = 3181,
      dhead = 107,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      role1 = 2164000,
      role2 = 201113,
      role3 = 201206,
      role5 = 2164404,
      role6 = 21635006,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "I feel it... will soon stop beating.",
      next = {110}
    },
    [110] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "All of a sudden, I practically saw the man before me get crushed by unseen despair.",
      next = {111}
    },
    [111] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202102,
      role3 = 202202,
      role6 = 21635006,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "He drooped his head and buried his face gently in the palm of my hand.",
      next = {112}
    },
    [112] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      roleanim = 1.2,
      ruchang = 9,
      sentence = "You're trying to punish me, aren't you?",
      voice = 2,
      next = {113}
    },
    [113] = {
      beijing = 3181,
      dhead = 118,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "I am not trying to punish you, Lucien.",
      next = {114}
    },
    [114] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "My hand felt the bitter, stinging dampness of his tears. It clung to my skin, malingering like this dead end that we were facing.",
      next = {115}
    },
    [115] = {
      beijing = 3181,
      dhead = 104,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "Any naivete or romance I had was wiped away that day. I... I'm tired.",
      next = {116}
    },
    [116] = {
      beijing = 3181,
      dhead = 105,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "I want to hate you, but I know I'm not able to. I want to love you, but I don't dare let myself.",
      next = {117}
    },
    [117] = {
      beijing = 3181,
      dhead = 106,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "I, myself... hate what I've become.",
      next = {118}
    },
    [118] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "Deathly stillness pervaded the gloomy room. When the sun had sunk to the West and the morning dew had dried, Lucien's raspy voice finally spoke up.",
      next = {119}
    },
    [119] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "39_Vampire_Romance",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "If you don't dare love Lucien, my lady, then could you at least pity Simon?",
      voice = 2,
      next = {120}
    },
    [120] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202202,
      role6 = 21635006,
      roleanim = 1.2,
      ruchang = 9,
      sentence = "Never before had he begged of me like this. I couldn't refuse.",
      next = {121}
    },
    [121] = {
      beijing = 3181,
      dhead = 104,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "...Alright.",
      next = {122}
    },
    [122] = {
      beijing = 3181,
      dhead = 101,
      dialog = 1,
      music = "39_Vampire_Romance",
      renming = "$u",
      renwu = "npc",
      sentence = "Simon, my most loyal servant, might I entreat you to act out that play from when I first saw you?",
      next = {123}
    },
    [123] = {
      beijing = 3181,
      dialog = 3,
      music = "39_Vampire_Romance",
      renwu = "npc",
      sentence = "Lucien nodded. His face was hidden in the evening shadows, so there was only the sound of his steadfast voice.",
      next = {124}
    },
    [124] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "58_2020Halloween",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202203,
      role6 = 21635006,
      ruchang = -1,
      sentence = "I have committed an unpardonable sin. I drank an incurable poison.",
      voice = 2,
      next = {125}
    },
    [125] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "58_2020Halloween",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202203,
      role6 = 21635006,
      sentence = "That mysterious elixir, sometimes honey, sometimes gall—with just one taste can be my soul's downfall.",
      voice = 2,
      next = {126}
    },
    [126] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "58_2020Halloween",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202203,
      role6 = 21635006,
      sentence = "Your sweet voice has incinerated my reason, leaving me wanting nothing but to follow you over Lethe and into Hell.",
      voice = 2,
      next = {127}
    },
    [127] = {
      beijing = 3181,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "58_2020Halloween",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2163000,
      role2 = 202101,
      role3 = 202203,
      role6 = 21635006,
      ruchang = 9,
      sentence = "So kiss me please, my love, with your poisoned lips.",
      voice = 2,
      next = {128}
    },
    [128] = {
      beijing = 3181,
      dialog = 3,
      mask = "alarm",
      music = "58_2020Halloween",
      renwu = "npc",
      sentence = "As I listened to his steady voice, my vision blurred. The last thing I saw, Lucien had taken out that stiletto and pointed it at his own chest.",
      sfx = "spring_sword",
      next = {129}
    },
    [129] = {
      beijing = 3181,
      bganim = 0,
      dialog = 3,
      music = "58_2020Halloween",
      renwu = "npc",
      sentence = "—At the final moment, I remembered:",
      next = {130}
    },
    [130] = {
      beijing = 3181,
      dialog = 3,
      music = "58_2020Halloween",
      renwu = "npc",
      sentence = "The reason I brought Simon back that day was because he had performed a love tragedy ending in a sublime, heart-shattering double suicide.",
      next = {0}
    }
  },
