    [7] = {
      beijing = 2132,
      dialog = 3,
      music = "10_Happy_Family",
      renwu = "npc",
      sentence = "Since the cave wasn't long at all, we hadn't gone far when the path started getting brighter. There was a faint sound of flowing water, and then the darkness gave way—",
