    [8] = {
      beijing = 4925,
      bganim = 0,
      dialog = 3,
      music = "07_Romantic",
      renwu = "npc",
      sentence = "The dreamy setting sun shined from a distance on a mountain waterfall spilling down before us. Where water and sky met, a rainbow formed in the spray.",
