    [17] = {
      beijing = 4925,
      dialog = 3,
      music = "07_Romantic",
      renwu = "npc",
      sentence = "There was the moonlit lake where the warrior and princess professed their mutual feelings for each other, and the castle where they defeated the evil dragon, and the field of flowers where the two reunited.",
